'use strict';

/**
* LAPACK routine to return the value of the one-norm, Frobenius norm, infinity-norm, or the largest absolute value of any element of a real symmetric matrix supplied in packed form.
*
* @module @stdlib/lapack/base/dlansp
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dlansp = require( '@stdlib/lapack/base/dlansp' );
*
* // AP = [ 1.0, 2.0, 5.0 ] (2x2 symmetric packed column-major upper)
* var AP = new Float64Array( [ 1.0, 2.0, 5.0 ] );
*
* var norm = dlansp( 'column-major', 'M', 'upper', 2, AP );
* // returns 5.0
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dlansp = require( '@stdlib/lapack/base/dlansp' );
*
* // AP = [ 1.0, 2.0, 5.0 ] (2x2 symmetric packed column-major upper)
* var AP = new Float64Array( [ 1.0, 2.0, 5.0 ] );
*
* var norm = dlansp.ndarray( 'column-major', 'M', 'upper', 2, AP, 1, 0 );
* // returns 5.0
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var dlansp;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dlansp = main;
} else {
	dlansp = tmp;
}


// EXPORTS //

module.exports = dlansp;

// exports: { "ndarray": "dlansp.ndarray" }
